{
  "report": "Resumo executivo (05/03/2025): ENEV3 mostra um viés neutro com leve tendência de queda no curto/médio prazo. Após alta entre set/out 2024 (pico ~R$14,3–14,5) a ação entrou em forte correção até um fundo próximo de R$9,5 em jan/2025; houve recuperação até fev, mas nas últimas sessões a alta perdeu força e o preço recuou para cerca de R$11,7. A estrutura técnica atual é de consolidação num contexto de médio prazo ainda baixista.",
  "signal": "Neutro",
  "support_levels": [
    11.3,
    10.0,
    9.5
  ],
  "resistance_levels": [
    12.0,
    12.6,
    13.5
  ],
  "indicator_readings": [
    {
      "indicator": "Preço (fechamento)",
      "reading": "≈ R$11,7 (05/03/2025)",
      "interpretation": "Recuperação parcial desde o fundo de jan, mas atualmente abaixo das médias curtas (MM20/EMA9) e abaixo da MM200 — mostra fraqueza relativa e consolidação."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$12,0",
      "interpretation": "Média curta está acima do preço — atua como resistência de curto prazo; inclinação recente plana/ligeiramente descendente."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$11,3",
      "interpretation": "Primeiro suporte relevante — preço está acima da MM50, o que limita queda imediata enquanto mantida."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$12,6",
      "interpretation": "Média de longo prazo ainda acima do preço; estrutura de médio/longo prazo permanece baixista enquanto não for recuperada."
    },
    {
      "indicator": "EMA9 / EMA21",
      "reading": "EMA9 ≈ R$12,0; EMA21 ≈ R$11,9",
      "interpretation": "EMAs reagiram à recuperação de jan/fev, mas a EMA9 aproxima-se do preço e perdeu momentum — cruzamento favorável no passado recente perdeu força."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD próximo de zero, linha MACD cruzando abaixo da linha de sinal (histograma negativo pequeno)",
      "interpretation": "Momentum de alta que apareceu em jan/fev enfraqueceu; sinal de curto prazo fica neutro/baixa enquanto MACD permanecer abaixo da linha de sinal."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Bandas moderadamente largas após alta/baixa; atualmente em leve contração",
      "interpretation": "Volatilidade aumentou durante a queda e recuperação; contração atual sugere consolidação e possível pausa antes do próximo movimento."
    },
    {
      "indicator": "RSI (14)",
      "reading": "≈ 45–50",
      "interpretation": "Zona neutra — saiu da sobrevenda, mas não há sobrecompra; tendência do RSI aponta para enfraquecimento do rali."
    },
    {
      "indicator": "Volume",
      "reading": "Picos isolados em pontos-chave (setembro/novembro/jan/fev); volume recente médio/baixo",
      "interpretation": "Recuperação não foi consistentemente confirmada por aumento de volume sustentado — menor convicção para continuação da alta."
    }
  ]
}
